module ClustersTest

using Test
using KernelSmoothing
using LinearAlgebra: diag, eigvals, Symmetric

# reference values from nprobust 1.0.0, generated by data/cluster_golden.R
include(joinpath(@__DIR__, "data", "cluster_golden.jl"))

# the data of the reference values: 400 observations at 101 distinct values, in 37
# clusters spread over x (G) or 11 clusters of neighbouring x (GX)
const I = 1:400
const X = round.(mod.(I .* 0.6180339887498949, 1), digits = 2)
const G = 1 .+ mod.(I, 37)
const GX = 1 .+ floor.(Int, X .* 10)
const Y = sin.(2π .* X) .+ 0.3 .* sin.(7.3 .* I) .+ 0.4 .* sin.(3.1 .* G)
const W = 1.0 .+ mod.(I, 3)
const EVAL = [0, 0.05, 0.3, 0.5, 0.77, 1]
const NPKERNELS = Dict("epa" => EpanechnikovKernel(), "tri" => TriangularKernel(), "uni" => UniformKernel())

crtype(v) = parse(Int, v[3:end])

@testset "agrees with nprobust" begin
  for c in LPCLUSTER, compat in (true, false)
    s = c.scale
    m = fit(LocalPolynomialRegression, s .* X, Y; weights = c.weighted ? W : nothing,
            cluster = c.xclusters ? GX : G, degree = c.p, derivative = c.deriv, kernel = NPKERNELS[c.kernel],
            bandwidth = s * c.h, pilot = s * c.b, points = s .* EVAL, vce = ClusterVariance(crtype(c.vce)),
            minobs = 0, compat)
    @test m.nwindow == c.N
    @test all(isapprox.(m.estimate, c.tau_us; rtol = 1e-10))
    @test all(isapprox.(m.estimate_bc, c.tau_bc; rtol = 1e-10))
    @test all(isapprox.(m.se, c.se_us; rtol = 1e-10))
    # for types 2 and 3, the bias-corrected standard errors depart from nprobust's
    # by default (see the invariance tests)
    if compat || c.vce == "cr1"
      @test all(isapprox.(m.se_rbc, c.se_rb; rtol = 1e-10))
    end
  end
end

@testset "bandwidths agree with nprobust" begin
  for c in LPBWCLUSTER
    d = SmoothingData(X, Y; weights = c.weighted ? W : nothing, cluster = G)
    base = c.bwselect == "imse-dpi" ? IMSEOptimal() : MSEOptimal()
    rule = c.bwselect == "ce-rot" ? CoverageOptimal(base) : base
    s = selectbandwidth(rule, d, NPKERNELS[c.kernel]; degree = c.p, derivative = c.deriv, points = [0, 0.3, 0.5, 1],
                        vce = ClusterVariance(crtype(c.vce)), compat = true)
    @test [s.h;] ≈ c.h rtol = 1e-7
    @test [s.details.b;] ≈ c.b rtol = 1e-7
  end
  # with clusters, the default variance estimator is CR1, as in nprobust
  c = LPBWCLUSTER[5]
  m = fit(LocalPolynomialRegression, X, Y; cluster = G, points = [0, 0.3, 0.5, 1], compat = true)
  @test m.vce == ClusterVariance(1)
  @test m.selection.h ≈ only(c.h) rtol = 1e-7
end

@testset "one observation per cluster" begin
  pts = [0.0, 0.05, 0.3, 0.77, 1.0]
  for (p, ν, h, b) in ((1, 0, 0.15, 0.25), (2, 1, 0.25, 0.2)), t in 0:3
    kw = (degree = p, derivative = ν, bandwidth = h, pilot = b, points = pts, minobs = 0)
    mc = fit(LocalPolynomialRegression, X, Y; cluster = I, vce = ClusterVariance(t), kw...)
    mh = fit(LocalPolynomialRegression, X, Y; vce = HCVariance(t), kw...)
    # CR3 has the factor (G - 1) / G, with G the observations in the window
    f = t == 3 ? sqrt.((mc.nwindow .- 1) ./ mc.nwindow) : ones(length(pts))
    @test mc.se ≈ mh.se .* f rtol = 1e-12
    @test mc.se_rbc ≈ mh.se_rbc .* f rtol = 1e-12
    @test vcov(mc) ≈ vcov(mh) .* (f * f') rtol = 1e-12
    @test vcov(mc; method = RobustBiasCorrected()) ≈ vcov(mh; method = RobustBiasCorrected()) .* (f * f') rtol = 1e-12
  end
  # the plug-in rules estimate their variances in the same way
  d, dc = SmoothingData(X, Y), SmoothingData(X, Y; cluster = I)
  for t in 0:2, rule in (MSEOptimal(), IMSEOptimal())
    sh = selectbandwidth(rule, d, EpanechnikovKernel(); points = [0, 0.3, 1], vce = HCVariance(t))
    sc = selectbandwidth(rule, dc, EpanechnikovKernel(); points = [0, 0.3, 1], vce = ClusterVariance(t))
    @test sc.h ≈ sh.h rtol = 1e-10
  end
end

@testset "invariance" begin
  kw = (bandwidth = 0.15, pilot = 0.25, points = EVAL, minobs = 0)
  for t in 0:3
    m = fit(LocalPolynomialRegression, X, Y; cluster = G, vce = ClusterVariance(t), kw...)
    # the names and the order of the clusters and observations do not matter
    o = sortperm(Y)
    ms = fit(LocalPolynomialRegression, X[o], Y[o]; cluster = string.("c", 100 .- G[o]), vce = ClusterVariance(t), kw...)
    @test ms.se ≈ m.se rtol = 1e-12
    @test ms.se_rbc ≈ m.se_rbc rtol = 1e-12
    # nor do the units of x, unlike nprobust's adjustment of the bias-corrected residuals
    m10 = fit(LocalPolynomialRegression, 10 .* X, Y; cluster = G, vce = ClusterVariance(t), bandwidth = 1.5,
              pilot = 2.5, points = 10 .* EVAL, minobs = 0)
    @test m10.se ≈ m.se rtol = 1e-10
    @test m10.se_rbc ≈ m.se_rbc rtol = 1e-10
  end
  # nprobust's CR2 standard errors of the bias-corrected estimates at x and 10 x
  c1, c10 = LPCLUSTER[2], LPCLUSTER[end]
  @test c1.vce == c10.vce == "cr2" && c10.scale == 10
  @test maximum(c1.se_rb ./ c10.se_rb) > 1e5
end

@testset "covariances" begin
  pts = [0.1, 0.15, 0.2, 0.5, 0.9]
  for t in 0:3, compat in (false, true)
    m = fit(LocalPolynomialRegression, X, Y; cluster = G, vce = ClusterVariance(t), bandwidth = 0.08, points = pts,
            compat)
    for method in (Conventional(), RobustBiasCorrected())
      C = vcov(m; method)
      @test diag(C) ≈ stderror(m; method) .^ 2 rtol = 1e-12
      @test minimum(eigvals(Symmetric(C))) >= -1e-12 * maximum(diag(C))
    end
  end
  # clusters of neighbouring x: estimates whose windows share no cluster are uncorrelated
  m = fit(LocalPolynomialRegression, X, Y; cluster = GX, bandwidth = 0.08, points = [0.15, 0.25, 0.55])
  C = vcov(m)
  @test C[1, 3] == 0 && C[1, 2] != 0
  @test confband(m).critical > 1.96
end

@testset "few clusters" begin
  # a window inside one cluster has no cluster-robust variance
  for t in 0:3
    m = fit(LocalPolynomialRegression, X, Y; cluster = GX, vce = ClusterVariance(t), bandwidth = 0.035,
            points = [0.05, 0.5], minobs = 0)
    @test isnan(m.se[1]) && isnan(m.se_rbc[1])
    @test isfinite(m.estimate[1]) && all(isfinite, (m.se[2], m.se_rbc[2]))
  end
  # where the fit is not identified, in a window with one distinct value or none
  m = fit(LocalPolynomialRegression, X, Y; cluster = G, bandwidth = [0.006, 0.004], points = [0.5, 0.505], minobs = 0)
  @test all(isnan, m.estimate) && all(isnan, m.se) && m.nwindow[2] == 0
  C = vcov(m)
  @test isnan(C[1, 1]) && C[2, 2] == 0
  # and the plug-in rules cannot estimate their variance constants there
  e = try
    selectbandwidth(MSEOptimal(), SmoothingData(X, Y; cluster = X .< 0.5), EpanechnikovKernel(); points = [0.05])
  catch err
    err
  end
  @test e isa ArgumentError && occursin("fewer than two clusters", e.msg)
end

@testset "data" begin
  d = SmoothingData([0.3, 0.1, 0.2, 0.1], [1.0, 2.0, 3.0, 4.0]; cluster = ["b", "a", "b", "c"])
  @test d.cluster == [2, 3, 1, 1]   # numbered by first appearance, stored in the order of x
  @test sprint(show, d) == "SmoothingData(4 observations, 3 distinct values, with responses, 3 clusters)"
  # observations with zero weight are dropped, with their clusters
  dw = SmoothingData([0.3, 0.1, 0.2, 0.1], [1.0, 2.0, 3.0, 4.0]; weights = [0, 1, 1, 1], cluster = ["b", "a", "b", "c"])
  @test dw.cluster == [1, 3, 2]
  @inferred SmoothingData(X, Y; cluster = G)
  @inferred fit(LocalPolynomialRegression, X, Y; cluster = G, bandwidth = 0.2, points = [0.5])
  @test @inferred(fit(LocalPolynomialRegression, X, Y; cluster = G, bandwidth = 0.2, points = [0.5])).vce ==
        ClusterVariance(1)
  @test occursin("in 37 clusters", sprint(show, MIME"text/plain"(), fit(LocalPolynomialRegression, X, Y; cluster = G,
                                                                          bandwidth = 0.2, points = [0.5])))
end

@testset "honest intervals" begin
  m = fit(LocalPolynomialRegression, X, Y; cluster = G, bandwidth = 0.2, points = [0.3, 0.5])
  ci = confint(m; method = Honest(10.0))
  @test all(ci[:, 2] .- ci[:, 1] .> 2 * 1.959 .* m.se)
  s = selectbandwidth(FLCIOptimal(10.0), SmoothingData(X, Y; cluster = G), EpanechnikovKernel(); points = [0.5])
  @test 0 < only(s.h) < 1
end

@testset "errors" begin
  @test_throws ArgumentError ClusterVariance(4)
  @test_throws ArgumentError fit(LocalPolynomialRegression, X, Y; vce = ClusterVariance(), bandwidth = 0.2)
  @test_throws ArgumentError fit(LocalPolynomialRegression, X, Y; cluster = G, vce = HCVariance(1), bandwidth = 0.2)
  @test_throws ArgumentError fit(LocalPolynomialRegression, X, Y; cluster = G, vce = NNVariance(), bandwidth = 0.2)
  @test_throws ArgumentError selectbandwidth(MSEOptimal(), SmoothingData(X, Y; cluster = G), EpanechnikovKernel();
                                             vce = HCVariance(1))
  @test_throws DimensionMismatch SmoothingData(X, Y; cluster = G[1:10])
  @test_throws ArgumentError SmoothingData([1.0, 2.0], [1.0, 2.0]; cluster = [1, missing])
  d = SmoothingData(X, Y; cluster = G)
  @test_throws ArgumentError fit(KDE, d)
  @test_throws ArgumentError fit(PointwiseDensity, d)
  @test_throws ArgumentError fit(LocalPolynomialDensity, d)
end

end
